package com.mo.economy_system.target.forge1201.network;
import com.mo.economy_system.common.market.MarketOrderType;import com.mo.economy_system.common.network.*;import com.mo.economy_system.platform.item.ItemStackSnapshotCodec;import io.netty.handler.codec.DecoderException;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.FriendlyByteBuf;import java.util.*;
final class Forge1201MarketDataCodec {
 static void encodeRequest(MarketDataRequestMessage m,FriendlyByteBuf b){b.writeLong(m.requestId());b.writeEnum(m.purpose());b.writeInt(m.offset());b.writeInt(m.limit());b.writeEnum(m.filter());b.writeUtf(m.query(),EconomyNetworkLimits.MAX_MARKET_QUERY_LENGTH);}
 static MarketDataRequestMessage decodeRequest(FriendlyByteBuf b){try{return new MarketDataRequestMessage(b.readLong(),readEnum(b,MarketDataRequestPurpose.values()),b.readInt(),b.readInt(),readEnum(b,MarketOrderFilter.values()),b.readUtf(EconomyNetworkLimits.MAX_MARKET_QUERY_LENGTH));}catch(RuntimeException e){throw new DecoderException("invalid market request",e);}}
 static void encodeResponse(MarketDataResponseMessage m,FriendlyByteBuf b){MarketDataPayloadBudget.requireWithinLimit(m);b.writeEnum(m.kind());b.writeLong(m.requestId());b.writeLong(m.marketRevision());b.writeInt(m.offset());b.writeInt(m.limit());b.writeInt(m.totalMatched());b.writeInt(m.totalSales());b.writeInt(m.totalDemand());b.writeInt(m.orders().size());for(var o:m.orders())writeOrder(o,b);}
 static MarketDataResponseMessage decodeResponse(FriendlyByteBuf b){try{if(b.readableBytes()>EconomyNetworkLimits.MAX_MARKET_RESPONSE_WIRE_BYTES)throw new DecoderException("market response exceeds wire limit");var kind=readEnum(b,MarketDataResponseKind.values());long id=b.readLong(),revision=b.readLong();int offset=b.readInt(),limit=b.readInt(),matched=b.readInt(),sales=b.readInt(),demand=b.readInt(),size=b.readInt();if(size<0||size>EconomyNetworkLimits.MAX_MARKET_PAGE_SIZE)throw new DecoderException("invalid order count");List<MarketOrderSnapshot> orders=new ArrayList<>(size);for(int i=0;i<size;i++)orders.add(readOrder(b));return new MarketDataResponseMessage(kind,id,revision,offset,limit,matched,sales,demand,orders);}catch(RuntimeException e){if(e instanceof DecoderException d)throw d;throw new DecoderException("invalid market response",e);}}
 private static void writeOrder(MarketOrderSnapshot o,FriendlyByteBuf b){b.writeEnum(o.type());b.writeUUID(o.tradeId());b.writeNbt(ItemStackSnapshotCodec.encode(o.item()).orElseThrow());b.writeInt(o.quantity());b.writeInt(o.totalPrice());b.writeUtf(o.ownerName(),EconomyNetworkLimits.MAX_MARKET_OWNER_NAME_LENGTH);b.writeUUID(o.ownerId());b.writeLong(o.listingTime());b.writeLong(o.expirationTime());b.writeBoolean(o.delivered());}
 private static MarketOrderSnapshot readOrder(FriendlyByteBuf b){MarketOrderType type=readEnum(b,MarketOrderType.values());UUID id=b.readUUID();CompoundTag tag=b.readNbt();if(tag==null)throw new DecoderException("missing snapshot");return new MarketOrderSnapshot(type,id,ItemStackSnapshotCodec.decode(tag).orElseThrow(),b.readInt(),b.readInt(),b.readUtf(EconomyNetworkLimits.MAX_MARKET_OWNER_NAME_LENGTH),b.readUUID(),b.readLong(),b.readLong(),b.readBoolean());}
 private static <E>E readEnum(FriendlyByteBuf b,E[] values){int ordinal=b.readVarInt();if(ordinal<0||ordinal>=values.length)throw new DecoderException("invalid enum");return values[ordinal];}
}
